/**
 * Generate a cryptographically secure CSRF token.
 * 
 * Creates a 64-character hexadecimal string (256 bits of entropy) suitable
 * for CSRF protection. Uses the Web Crypto API's getRandomValues() method,
 * which provides cryptographically strong random values.
 * 
 * The token is generated by:
 * 1. Creating a 32-byte (256-bit) array
 * 2. Filling it with cryptographically secure random values
 * 3. Converting each byte to a 2-character hex string
 * 4. Concatenating all hex strings into a 64-character token
 * 
 * This level of entropy (256 bits) makes the token computationally infeasible
 * to guess or brute force.
 * 
 * Note: If globalThis.crypto is unavailable, this will throw a TypeError. Crypto availability
 * is validated upstream during session operations.
 * @see {SessionCrypto}
 * 
 * @returns A 64-character hexadecimal CSRF token
 * 
 * @example
 * ```typescript
 * const token = createCsrfToken();
 * console.log(token.length); // 64
 * console.log(token); // "a3f7b2c9d4e5f6a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2e3f4a5"
 */
export function createCsrfToken(): string {
  const array = new Uint8Array(32);
  globalThis.crypto.getRandomValues(array);
  return Array.from(array)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}
